"""Preserve the seven remaining fifth-rank Enchantment sources; never approve them."""
import json
from prepare_spell_source_cohort import prepare, AUDIT

QUESTIONS = {
    'dominate-monster': 'Preserve control of ANY creature of CR10orless, WIS save EACH TURN, Core Action/60ft/concentration up to one minute. Define what actual CR evidence qualifies, including player characters or shapechanged creatures without a CR, without substituting level,tier or appearance. Specify initial save and exact repeat-save marker, commands and communication, issue/change costs, target action/movement/reaction/resource permissions, unsafe or self-destructive orders, standing orders and unavailable commands. Reconcile the reviewed Dominate Beast command channel, compelled-budget priority and source-character/target/encounter hard-control history. Decide whether control establishes Charmed or another distinct effect; immunity to one is not automatically immunity to all control. No extra turns, remote sight, new statblock, formula knowledge, companion bond, forced optional RP spending or encounter-reset renewal from changing controllers.',
    'mass-sleep': 'Preserve exactly60HP worth of creatures sleeping for1minute, Core Action/60ft/1minute. Define actual area or finite target-selection region, target eligibility, perception/line of effect, ordering and ties, current versus maximum HP, temporary HP and how the remaining60HP pool is spent or skipped. Compare the reviewed Sleep procedure explicitly without silently importing outside-game dice. Give save or no-save handling, sleep/Unconscious condition, waking by damage or real assistance, immunity and hard-control admission, including an already-asleep target and a creature whose HP changes during the snapshot. Decide how a target blocked by control history affects allocation without leaking hidden HP/immunity. No overflow damage, HP drain, permanent coma, free reallocation after results or sleep-based rest credit.',
    'group-illusion': 'Preserve creation of an illusionary PARTY OF ALLIES that misdirects one target enemy, Enchantment school, Core Action/60ft/concentration up to one minute. Define a finite image count,size,placement,motion,senses, caster control cost and who perceives the images. Resolve whether this is an external illusion or one target\'s mental effect, with actual initial/repeat disbelief or save procedures and a finite meaning for misdirected. Distinguish mistaken information/target selection from forced actions and hard control; decide interaction with true sight, touch, attacks, area damage and existing Mirror Image/Silent Image source boundaries. No actual creatures, extra attacks, occupied spaces, flanking, cover, carrying, shared senses or freely chosen stolen actions arise from the word allies. State effect-ending and suppression without delayed commands.',
    'mental-bomb': 'Preserve ALL enemies in20ft RADIUS taking4d6 psychic and losing their NEXT REACTION. Core specifically says1REACTION/range20ft/Instantaneous, with no trigger. Resolve that missing trigger explicitly; do not silently turn it into an Action or allow an anytime extra cast. Separate cast-point range from radius and define center, geometry, enemy selection from actual information, sight/line of effect, save and distinct damage/denial outcomes. Define next reaction as a specific finite resource/trigger prohibition or other explicit model, with expiry for an already-spent or unavailable reaction, off-turn timing, extra turns and source-specific reaction slots. Address whether the triggering reaction is interrupted before commitment or a later one is lost, avoiding retroactive refunds. Preserve hard-control/component-family rules where applicable, duplicate effects and zero-damage cases. No banked permanent reaction debt or automatic caster knowledge of hidden enemies.',
    'hold-monster': 'Preserve one target Paralyzed for1minute with WIS save ends, Core Action/60ft/1minute (no source concentration marker). Define actual eligible creature classes and size limits only where sourced or expressly NEW; Monster alone cannot exclude players, Undead or companions. Resolve initial save and exact repeated-save cadence, conscious/perception requirements, concentration if added and the minute endpoint. Apply actual Paralyzed consequences and existing source-character/target/encounter hard-control admission without changing the base condition. Define immunity, suppression, death, removal and overlapping sources; a blocked initial establishment cannot wait and reapply later. Do not add damage, physical binding, restraint object, automatic critical effects beyond the current condition or a familiar-game immunity that our source does not supply.',
    'geas': 'Preserve forcing one target to follow a command for30DAYS, WIS negates, Core Action/60ft/30days. Do not replace the stated compulsion with an imported once-per-day psychic punishment or silently shorten its lifetime. Define a finite command, comprehension, feasibility, scope, prohibited self-destructive/harmful/resource-spending orders, actual enforcement and caster amendment limits. Reconcile long-duration compulsion with existing compelled-budget priority, hard-control source/target/encounter history, voluntary choice, multiple controllers and ordinary action economy. Specify refusal/impossibility consequences only if expressly NEW, command completion, caster/target death, dispelling/suppression, calendar/time-loop anchoring and whether it is a curse or Charmed effect. No automatic loyalty, ownership, legal consent, alignment change, telepathy, action generation or knowledge of unseen compliance. Any unresolved calendar/time-loop dependency must stay explicit rather than reset30days by rest or encounter changes.',
    'mind-fog': 'Preserve creatures IN AN AREA having disadvantage on BOTH WIS saves and WIS checks, Core Action/60ft/Instantaneous with WIS-save resolution. Define finite area geometry, center/placement, lifetime/concentration and actual initial save, including whether its own save is affected before establishment. Decide an area-tied continuing modifier versus a bounded effect carried by failed targets, with entry/exit/reentry and repeat saves, suppression, overlapping casts and extra turns. Ordinary advantage/disadvantage rules remain; no stacking extra dice or hidden penalty. Specify perception/line of effect and whether fog is a visual obstruction, mental phenomenon or explicit NEW physical cloud; the name alone supplies no Blinded, poisonous vapor, suffocation, intelligence reduction or WIS-score change. Instantaneous must not conceal an undefined permanent debuff.'
}


def main():
    coverage = json.loads((AUDIT / 'FOCUSED_SPELL_SOURCE_PREPARATION_COVERAGE.json').read_text(encoding='utf-8'))
    assert len(coverage['cohortFiles']) == 12 and coverage['distinctPreparedPendingSpellIds'] == 210
    prepare(
        prefix='ENCHANTMENT_RANK5', title='Remaining rank-five Enchantment source audit',
        questions=QUESTIONS,
        selector=lambda r: r['operational'] is None and 'Enchantment' in r['schools'] and r['id'] != 'synaptic-static' and min(v['rank'] for v in r['classAccess'].values()) == 5,
        expected_count=7, question_prefix='EN5', prior_files=coverage['cohortFiles'], expected_prior_count=210,
        counterpart_ids=['dominate-beast', 'sleep', 'command', 'charm-person', 'hypnotic-pattern',
                         'confusing-flash', 'silent-image', 'mirror-image'],
        pending_ids=['confusion', 'compulsion', 'synaptic-static', 'frozen-tomb'],
        extra_excerpts={
            'CONDITIONS_PLAYTEST.md': ['Paralyzed', 'Unconscious', 'Charmed'],
            'CREATURE_LIFECYCLE_PLAYTEST.md': ['At the table', 'Different kinds of creature life', 'Stats and ownership', 'Dominate Beast integration'],
        },
        introduction='Seven remaining fifth-rank Enchantment identities retain their exact Core and book text. Synaptic Static is already preserved with both placements in the preceding Evocation cohort and is included only as a pending comparison here. Mental Bomb retains its unexplained Reaction casting time; Geas retains its30-day compulsion; Hold Monster keeps the absent concentration marker. These are questions for future source conference, not mechanical edits. No cosmology, faction or alignment review is performed.',
        future_dispatch='Prepared only while Mining/shared gathering-tool source review is active in Calibration Review Part 2. Preserve this revision and rebase relevant dependencies before future dispatch. Source decisions precede authored cards and separate exact review. Cosmology remains after verified GitHub push.')


if __name__ == '__main__':
    main()
